sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.rating = 0;
    c.hoverRating = 0;
    c.feedback = '';
    c.needsHelp = false;
    c.errorMsg = '';
    c.submitting = false;

    c.setRating = function(val) {
        c.rating = val;
    };
    c.setHover = function(val) {
        c.hoverRating = val;
    };
    c.clearHover = function() {
        c.hoverRating = 0;
    };

    c.submit = function() {
        if (!c.rating) {
            c.errorMsg = 'Please provide an overall rating before submitting.';
            return;
        }
        c.errorMsg = '';
        c.submitting = true;

        // Populate c.data directly for c.server.update()
        c.data.action = 'submit_checkin';
        c.data.rating = c.rating;
        c.data.feedback = c.feedback;
        c.data.questionAnswers = c.data.questions;
        c.data.needsHelp = c.needsHelp;

        // Native Service Portal two-way synchronization
        c.server.update().then(function(response) {
            c.submitting = false;
            // The template switches automatically to the Thank You screen
            // when c.data.submitted is true
        }).catch(function(err) {
            c.submitting = false;
            c.errorMsg = 'Submission failed: ' + (err.message || 'Server error occurred');
        });
    };
};

sp_widget.css:
.retention-checkin-wrapper {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 15px;
  background-color: $background-primary;
}

.checkin-card {
  max-width: 680px;
  width: 100%;
  border-radius: $border-radius-large;
  overflow: hidden;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
  background: $background-secondary;
}

.checkin-header {
  background-color: $brand-primary-dark;
  color: #fff;
  padding: 28px 32px;
  text-align: center;
}

.checkin-header i {
  margin-bottom: 8px;
  opacity: 0.85;
}

.checkin-header h2 {
  margin: 8px 0 0;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 0.5px;
  color: #fff;
}

.checkin-body {
  padding: 32px;
}

/* Candidate Info Bar */
.candidate-info {
  display: flex;
  justify-content: space-around;
  padding: 16px;
  margin-bottom: 24px;
  border-radius: $border-radius-base;
  background: $background-tertiary;
}

.info-item {
  display: flex;
  align-items: center;
  gap: 8px;
  color: $text-color;
  font-weight: 500;
}

.info-item i {
  color: $brand-info;
}

/* Section Titles */
.section-title {
  font-size: 15px;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 12px;
}

.section-title i {
  color: $brand-info;
  margin-right: 6px;
}

/* Questions */
.questions-section {
  margin-bottom: 28px;
  padding: 20px;
  border-radius: $border-radius-base;
  border-left: 4px solid $brand-info;
  background: $background-tertiary;
}

.question-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.question-list li {
  padding: 8px 0;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  color: $text-color;
  font-size: 14px;
}

.question-list li i {
  color: $brand-info;
  margin-top: 3px;
  font-size: 11px;
}

/* Star Rating */
.rating-section {
  margin-bottom: 28px;
}

.star-rating {
  display: flex;
  justify-content: center;
  gap: 12px;
  padding: 16px 0;
}

.star {
  cursor: pointer;
  color: $border-secondary;
  transition: color 0.2s ease, transform 0.15s ease;
}

.star:hover,
.star.active {
  color: $brand-warning;
}

.star:hover {
  transform: scale(1.15);
}

.rating-labels {
  display: flex;
  justify-content: space-between;
  font-size: $font-size-small;
  color: $text-muted;
  padding: 0 20px;
}

/* Feedback */
.feedback-section {
  margin-bottom: 24px;
}

.feedback-textarea {
  resize: vertical;
  min-height: 100px;
  border: 1px solid $border-primary;
  border-radius: $border-radius-base;
  padding: 12px;
  font-size: $font-size-base;
  color: $text-color;
  background: $background-primary;
}

.feedback-textarea:focus {
  border-color: $brand-info;
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.15);
}

/* HR Support Toggle */
.hr-support-section {
  margin-bottom: 24px;
  padding: 16px;
  border-radius: $border-radius-base;
  background: $background-tertiary;
}

.hr-toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  margin: 0;
  font-weight: 500;
  color: $text-color;
}

.hr-toggle input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: $brand-info;
}

.toggle-label i {
  color: $brand-warning;
  margin-right: 4px;
}

/* Submit Button */
.submit-section {
  margin-top: 8px;
}

.submit-btn {
  padding: 14px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.5px;
  border-radius: $border-radius-base;
  border: none;
  background-color: $brand-info;
  color: #fff;
  transition: background-color 0.2s ease;
}

.submit-btn:hover:not(:disabled) {
  background-color: $brand-primary;
}

.submit-btn:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

/* Success State */
.success-icon {
  margin: 20px 0 16px;
}

.success-icon i {
  color: $brand-success;
}

.thank-you-title {
  font-size: 22px;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 12px;
}

.thank-you-message {
  font-size: 15px;
  color: $text-secondary;
  line-height: 1.6;
  max-width: 480px;
  margin: 0 auto;
}

/* Error Text */
.error-text {
  color: $brand-danger;
  font-size: 15px;
  margin: 20px 0;
}

/* Alert Overrides */
.alert-danger {
  border-radius: $border-radius-base;
  margin-bottom: 20px;
}

.alert-danger i {
  margin-right: 6px;
}

.qa-block {
  margin-bottom: 16px;
  background: $background-secondary;
  padding: 14px;
  border-radius: $border-radius-base;
  border: 1px solid $border-primary;
}

.qa-question-label {
  display: block;
  font-weight: 600;
  font-size: 14px;
  color: $text-color;
  margin-bottom: 8px;

  i {
    color: $brand-info;
    margin-right: 4px;
  }
}

.qa-answer-input {
  width: 100%;
  resize: vertical;
  background-color: $background-primary;
  border: 1px solid $border-primary;
  border-radius: $border-radius-base;
  color: $text-color;
  font-size: 13px;
  padding: 8px 12px;

  &:focus {
    border-color: $brand-info;
    box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.15);
  }
}

sp_widget.script:
(function() {
    data.submitted = false;
    data.candidateName = '';
    data.caseNumber = '';
    data.milestone = '';
    data.milestoneLabel = '';
    data.questions = [];
    data.thankYouMessage = '';
    data.errorMessage = '';

    // ── 1. Handle check-in submission ──
    if (input && input.action === 'submit_checkin') {
        try {
            var submitId = input.sys_id || $sp.getParameter('sys_id');
            if (!submitId) {
                data.errorMessage = 'Missing check-in identifier.';
                return;
            }

            var submitGr = new GlideRecord('x_2023506_german_1_ret_chkin');
            if (!submitGr.get(submitId)) {
                data.errorMessage = 'Check-in record not found for ID: ' + submitId;
                return;
            }

            // Compile question & answer responses into u_settling_feedback
            var compiledFeedback = '';
            if (input.questionAnswers && input.questionAnswers.length > 0) {
                compiledFeedback += '=== MILESTONE QUESTIONS & ANSWERS ===\n\n';
                for (var i = 0; i < input.questionAnswers.length; i++) {
                    var qa = input.questionAnswers[i];
                    var ansText = (qa.answer && qa.answer.toString().trim() !== '') ? qa.answer.toString().trim() : '[No response provided]';
                    compiledFeedback += (i + 1) + '. ' + qa.question + '\nAnswer: ' + ansText + '\n\n';
                }
            }

            if (input.feedback && input.feedback.toString().trim() !== '') {
                compiledFeedback += '=== ADDITIONAL EXPERIENCE & FEEDBACK ===\n' + input.feedback.toString().trim() + '\n';
            }

            // Set field values on the retention check-in record
            submitGr.setValue('u_sentiment_score', parseInt(input.rating, 10));
            submitGr.setValue('u_settling_feedback', compiledFeedback);
            submitGr.setValue('u_needs_intervention', input.needsHelp ? true : false);
            submitGr.setValue('u_status', 'completed');
            submitGr.update();

            data.submitted = true;
            data.thankYouMessage = 'Thank you for completing your check-in! Your responses have been successfully recorded.';

            // Reload candidate info for the thank-you screen
            var thankCaseGr = new GlideRecord('x_2023506_german_1_ret_case');
            if (thankCaseGr.get(submitGr.getValue('u_retention_case'))) {
                data.candidateName = thankCaseGr.getValue('u_candidate_name') || '';
            }
        } catch (e) {
            data.errorMessage = 'An error occurred while submitting: ' + e.message;
        }
        return;
    }

    // ── 2. Initial page load ──
    var sysId = $sp.getParameter('sys_id');
    if (!sysId) {
        data.errorMessage = 'No check-in ID provided. Please use the link from your invitation email.';
        return;
    }

    data.checkinSysId = sysId;

    var gr = new GlideRecord('x_2023506_german_1_ret_chkin');
    if (!gr.get(sysId)) {
        data.errorMessage = 'Check-in record not found for ID: ' + sysId;
        return;
    }

    // Check if already completed
    if (gr.getValue('u_status') === 'completed') {
        data.submitted = true;
        data.thankYouMessage = 'You have already completed this check-in. Thank you for your feedback!';
        var completedCase = new GlideRecord('x_2023506_german_1_ret_case');
        if (completedCase.get(gr.getValue('u_retention_case'))) {
            data.candidateName = completedCase.getValue('u_candidate_name') || '';
        }
        return;
    }

    data.milestone = gr.getValue('u_milestone') || '';
    data.milestoneLabel = gr.getDisplayValue('u_milestone') || '';

    // Load parent Retention Case details
    var caseGr = new GlideRecord('x_2023506_german_1_ret_case');
    if (caseGr.get(gr.getValue('u_retention_case'))) {
        data.candidateName = caseGr.getValue('u_candidate_name') || '';
        data.caseNumber = caseGr.getDisplayValue('number') || caseGr.getDisplayValue('sys_id');
    }

    // Milestone-specific questions
    var milestoneQuestionsMap = {
        '30_days': [
            'Have you completed your Anmeldung (city registration)?',
            'How is your initial settling-in experience?',
            'Have you opened a German bank account?'
        ],
        '60_days': [
            'How are your language/communication skills developing?',
            'Is your workplace integration going well?',
            'Any issues with health insurance or tax setup?'
        ],
        '90_days': [
            'How is your probation period going?',
            'Are you satisfied with your job responsibilities?',
            'Have you built a local support network?'
        ],
        '150_days': [
            'Do you feel established in Germany?',
            'Any remaining bureaucratic issues?',
            'Would you recommend this relocation experience?'
        ]
    };

    // Prepare questions array with individual answer bindings
    var rawQuestions = milestoneQuestionsMap[data.milestone] || [];
    data.questions = [];
    for (var j = 0; j < rawQuestions.length; j++) {
        data.questions.push({
            id: 'q_' + j,
            question: rawQuestions[j],
            answer: ''
        });
    }
})();
